const deals = $input.first().json.deals || [];
const date = new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
if (deals.length === 0) return [{ json: { skip: true } }];

const clean = v => (v && v !== 'nan' && v !== 'none') ? String(v).trim() : '';
const money = v => clean(v) || '—';
const truncate = (s, n) => s.length > n ? s.slice(0, n).replace(/\s+\S*$/, '') + '…' : s;

// Derive the hub base from any deal's research link, so the capabilities link
// tracks whatever DI_HUB_BASE_URL the backend is set to (local or production).
const anyHub = (deals.find(d => clean(d.hub_url)) || {}).hub_url || '';
const hubBase = anyHub ? anyHub.split('/docs/')[0] : 'https://intel.id8investments.com';
const capabilitiesUrl = `${hubBase}/docs/overview`;

const TIER_LABEL = {
  strong_go: 'Strong Go',
  go_ic: 'Go / IC Review',
  more_diligence: 'More Diligence',
  pass: 'Pass',
  watch_list: 'Watch List',
};
const TIER_COLOR = {
  strong_go:      { bg: '#eaf3de', text: '#2e6b1a' },
  go_ic:          { bg: '#eaf3de', text: '#2e6b1a' },
  more_diligence: { bg: '#fbf0d9', text: '#7a4f00' },
  pass:           { bg: '#f0f0f0', text: '#888' },
  watch_list:     { bg: '#e8eef5', text: '#33587a' },
};
const DIM_SHORT = {
  lead_round_dynamics:  'Lead / Round',
  founder_team_quality: 'Founder',
  fundamentals:         'Fundamentals',
  return_potential:     'Return',
  ai_score:             'AI',
  terms:                'Terms',
};

// Turn Perplexity's [1][3][4] markers into small superscript links to the sources.
// Markers without a matching citation are dropped instead of left dangling.
function linkifyCitations(text, citations) {
  citations = citations || [];
  return String(text || '').replace(/\[(\d+)\]/g, (m, n) => {
    const url = citations[parseInt(n, 10) - 1];
    if (!url) return '';
    return `<a href="${url}" style="color:#0066cc;text-decoration:none;"><sup style="font-size:8px;margin-left:1px;">${n}</sup></a>`;
  });
}

function fitBadge(d) {
  if (d.fit_score == null) return '';
  if (d.fit_hard_auto_pass) {
    const c = TIER_COLOR.pass;
    return `<span style="display:inline-block;padding:3px 10px;border-radius:3px;font-size:10px;font-weight:600;letter-spacing:0.06em;text-transform:uppercase;background:${c.bg};color:${c.text};">Hard Auto-Pass</span>`;
  }
  const tier = d.fit_tier || 'pass';
  const c = TIER_COLOR[tier] || TIER_COLOR.pass;
  const label = d.fit_gate ? `Clears Gate · ${TIER_LABEL[tier] || tier}` : (TIER_LABEL[tier] || tier);
  return `<span style="display:inline-block;padding:3px 10px;border-radius:3px;font-size:10px;font-weight:600;letter-spacing:0.06em;text-transform:uppercase;background:${c.bg};color:${c.text};">${label}</span>`;
}

function fitBlock(d) {
  if (d.fit_score == null) return '';

  const dims = (d.fit_params || []).map(p => `
    <td style="padding:0 10px 0 0;vertical-align:top;">
      <p style="margin:0 0 2px 0;font-size:9px;font-weight:600;letter-spacing:0.05em;text-transform:uppercase;color:#aaa;line-height:1.3;">${DIM_SHORT[p.key] || p.key}</p>
      <p style="margin:0;font-size:15px;font-weight:700;color:#111;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;">${p.score}<span style="font-size:11px;font-weight:400;color:#c4c4c4;">/4</span></p>
    </td>`).join('');

  const ratShort = linkifyCitations(truncate(clean(d.fit_rationale), 220), d.fit_citations);
  const hardPassReason = d.fit_hard_auto_pass ? clean(d.fit_hard_auto_pass_reason) : '';

  const hubLink = clean(d.hub_url)
    ? `<a href="${clean(d.hub_url)}" style="font-size:12px;font-weight:600;color:#0066cc;text-decoration:none;">Full research →</a>`
    : '';

  return `
  <table width="100%" cellpadding="0" cellspacing="0" style="margin-top:18px;">
    <tr><td style="border-top:1px solid #e4e4e2;padding-top:16px;">
      <table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:14px;">
        <tr>
          <td style="vertical-align:middle;">
            <span style="font-size:10px;font-weight:600;letter-spacing:0.1em;text-transform:uppercase;color:#aaa;">Deal Screen</span>
            <span style="font-size:18px;font-weight:700;color:#111;margin-left:10px;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;">${d.fit_score.toFixed(1)}<span style="font-size:13px;color:#bbb;font-weight:400;"> / 4.0</span></span>
            <span style="font-size:11px;color:#bbb;margin-left:6px;">(raw ${(d.fit_raw_score != null ? d.fit_raw_score : d.fit_score).toFixed(1)})</span>
          </td>
          <td align="right" style="vertical-align:middle;">${fitBadge(d)}</td>
        </tr>
      </table>
      <table cellpadding="0" cellspacing="0" style="margin-bottom:14px;"><tr>${dims}</tr></table>
      ${hardPassReason ? `<p style="margin:0 0 12px 0;font-size:12px;color:#7a4f00;line-height:1.6;"><strong>Hard auto-pass.</strong> ${hardPassReason}</p>` : ''}
      ${ratShort ? `<p style="margin:0 0 12px 0;font-size:12px;color:#666;line-height:1.6;">${ratShort}</p>` : ''}
      ${hubLink ? `<p style="margin:0;">${hubLink} <span style="color:#ccc;font-size:11px;">&nbsp;·&nbsp; Confidence: ${clean(d.fit_confidence) || '—'}</span></p>` : `<p style="margin:0;font-size:11px;color:#aaa;">Confidence: ${clean(d.fit_confidence) || '—'}</p>`}
    </td></tr>
  </table>`;
}

const dealBlocks = deals.map(d => {
  const nameStyle = "margin:0 0 3px 0;font-size:21px;font-weight:700;letter-spacing:-0.02em;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;";
  const companyName = d.record_id
    ? `<a class="deal-link" href="https://app.attio.com/i-d-8-investments/deals/record/${d.record_id}/overview" style="text-decoration:none;color:#111;">
        <h2 style="${nameStyle}color:inherit;display:inline-block;">${clean(d.company)}<span class="deal-arrow" style="font-size:16px;font-weight:600;color:#bbb;">&nbsp;↗</span></h2>
      </a>`
    : `<h2 style="${nameStyle}color:#111;">${clean(d.company)}</h2>`;

  return `
  <tr><td style="padding:0 0 40px 0;">
    <table width="100%" cellpadding="0" cellspacing="0">
      <tr>
        <td>
          ${companyName}
          ${clean(d.website) ? `<p style="margin:0 0 12px 0;font-size:13px;"><a href="https://${clean(d.website)}" style="color:#0066cc;text-decoration:underline;">${clean(d.website)}</a></p>` : ''}
        </td>
        <td align="right" style="vertical-align:top;padding-top:4px;">
          <span style="font-size:11px;font-weight:600;letter-spacing:0.08em;text-transform:uppercase;color:#666;background:#ededeb;padding:4px 10px;border-radius:4px;">${clean(d.series)}</span>
        </td>
      </tr>
    </table>
    ${clean(d.description) ? `<p style="margin:0 0 16px 0;font-size:14px;line-height:1.7;color:#444;">${clean(d.description)}</p>` : ''}
    <table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:14px;">
      <tr>
        <td style="width:33%;padding-right:12px;">
          <p style="margin:0 0 2px 0;font-size:10px;font-weight:600;letter-spacing:0.1em;text-transform:uppercase;color:#aaa;">Deal Size</p>
          <p style="margin:0;font-size:16px;font-weight:700;color:#111;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;">${money(d.deal_size)}</p>
        </td>
        <td style="width:33%;padding-right:12px;">
          <p style="margin:0 0 2px 0;font-size:10px;font-weight:600;letter-spacing:0.1em;text-transform:uppercase;color:#aaa;">Post Valuation</p>
          <p style="margin:0;font-size:16px;font-weight:700;color:#111;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;">${money(d.post_valuation)}</p>
        </td>
        <td style="width:33%;">
          <p style="margin:0 0 2px 0;font-size:10px;font-weight:600;letter-spacing:0.1em;text-transform:uppercase;color:#aaa;">Date</p>
          <p style="margin:0;font-size:16px;font-weight:700;color:#111;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;">${clean(d.deal_date) || '—'}</p>
        </td>
      </tr>
    </table>
    <table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:14px;">
      <tr>
        <td style="width:33%;padding-right:12px;vertical-align:top;">
          <p style="margin:0 0 2px 0;font-size:10px;font-weight:600;letter-spacing:0.1em;text-transform:uppercase;color:#aaa;">Location</p>
          <p style="margin:0;font-size:13px;color:#444;">${clean(d.hq_location) || '—'}</p>
        </td>
        <td style="width:33%;padding-right:12px;vertical-align:top;">
          <p style="margin:0 0 2px 0;font-size:10px;font-weight:600;letter-spacing:0.1em;text-transform:uppercase;color:#aaa;">Lead Investors</p>
          <p style="margin:0;font-size:13px;color:#444;">${clean(d.lead_investors) || '—'}</p>
        </td>
        <td style="width:33%;vertical-align:top;">
          <p style="margin:0 0 2px 0;font-size:10px;font-weight:600;letter-spacing:0.1em;text-transform:uppercase;color:#aaa;">New Investors</p>
          <p style="margin:0;font-size:13px;color:#444;">${clean(d.new_investors) || '—'}</p>
        </td>
      </tr>
    </table>
    <table width="100%" cellpadding="0" cellspacing="0">
      <tr>
        <td style="vertical-align:top;">
          <p style="margin:0 0 2px 0;font-size:10px;font-weight:600;letter-spacing:0.1em;text-transform:uppercase;color:#aaa;">All Investors</p>
          <p style="margin:0;font-size:13px;color:#444;">${clean(d.investors) || '—'}</p>
        </td>
      </tr>
    </table>
    ${fitBlock(d)}
  </td></tr>
  <tr><td style="padding:0 0 40px 0;"><div style="height:1px;background:#e4e4e2;"></div></td></tr>
`;
}).join('');

const screenedCount = deals.filter(d => d.fit_score != null).length;
const gatedCount = deals.filter(d => d.fit_gate).length;
const screenSummary = screenedCount
  ? `&nbsp;·&nbsp; ${screenedCount} screened · ${gatedCount} cleared the gate`
  : '';

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  .deal-link, .deal-link h2, .deal-arrow { transition:color 0.15s ease; }
  .deal-arrow { display:inline-block; transition:color 0.15s ease, transform 0.15s ease; }
  .deal-link:hover h2, .deal-link:hover .deal-arrow { color:#0066cc !important; }
  .deal-link:hover .deal-arrow { transform:translate(2px,-2px); }
</style>
</head>
<body style="margin:0;padding:0;background:#fafafa;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#fafafa;padding:48px 0;">
  <tr><td align="center">
    <table width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;">
      <tr><td style="padding:0 0 8px 0;">
        <img src="https://pb-attio-pipeline.onrender.com/logo" alt="ID8 Investments" height="22" style="display:block;margin:0 0 20px 0;">
        <h1 style="margin:0 0 6px 0;font-size:30px;font-weight:700;color:#111;letter-spacing:-0.03em;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;">Weekly Deal Flow</h1>
        <p style="margin:0 0 16px 0;font-size:14px;color:#888;">${date} &nbsp;·&nbsp; ${deals.length} new deal(s) added to Attio${screenSummary}</p>
        <p style="margin:0 0 28px 0;font-size:12px;"><a href="${capabilitiesUrl}" style="color:#0066cc;text-decoration:none;font-weight:600;">ID8 AI Intelligence — view all systems →</a></p>
        <div style="height:1px;background:#e4e4e2;margin-bottom:40px;"></div>
      </td></tr>
      ${dealBlocks}
      <tr><td style="padding:8px 0 0 0;">
        <p style="margin:0 0 6px 0;font-size:12px;"><a href="${capabilitiesUrl}" style="color:#0066cc;text-decoration:none;font-weight:600;">AI Capabilities & Systems →</a></p>
        <p style="margin:0;font-size:12px;color:#b0b0b0;">ID8 Investments LLC | 169 Hudson Street, New York, NY</p>
      </td></tr>
    </table>
  </td></tr>
</table>
</body>
</html>`;

return [{ json: { html, subject: `PitchBook Deal Flow — ${date} (${deals.length} new)` } }];
